const EV_KNOWN_TYPES = ['text', 'image', 'document', 'video', 'audio', 'sticker', 'location',
  'contacts', 'interactive', 'button', 'reaction', 'order', 'system', 'unsupported'];
const EV_MEDIA_TYPES = ['image', 'video', 'audio', 'document', 'sticker'];

const EV_INSTANCE_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/;
const EV_GROUP_RE = /^[0-9]{5,30}@g\.us$/;
const EV_LID_RE = /^[0-9]{5,25}@lid$/;
const EV_MSGID_RE = /^[^:\s]{1,128}$/;

const EV_FORBIDDEN_KEYS = ['apikey', 'apiKey', 'sender', 'server_url', 'serverUrl', 'destination',
  'base64', 'mediaKey', 'mediaKeyTimestamp', 'directPath', 'url', 'jpegThumbnail', 'messageSecret',
  'fileEncSha256', 'streamingSidecar', 'agency_id', 'channel_id', 'agent_id', 'create_sessions'];

const EV_MAX_TEXT = 65536;      // whatsapp_messages_body_check
const EV_MAX_RAW_TEXT = 8192;   // per-field cap inside raw_payload, as in the database rebuild
const EV_MAX_RAW_BYTES = 32768; // whatsapp_messages_evolution_raw_payload_safe

const EV_TYPE_BY_KEY = {
  conversation: 'text',
  extendedTextMessage: 'text',
  imageMessage: 'image',
  videoMessage: 'video',
  audioMessage: 'audio',
  ptvMessage: 'video',
  documentMessage: 'document',
  documentWithCaptionMessage: 'document',
  stickerMessage: 'sticker',
  locationMessage: 'location',
  liveLocationMessage: 'location',
  contactMessage: 'contacts',
  contactsArrayMessage: 'contacts',
  reactionMessage: 'reaction',
  orderMessage: 'order',
  protocolMessage: 'system',
  senderKeyDistributionMessage: 'system',
  buttonsResponseMessage: 'button',
  templateButtonReplyMessage: 'button',
  listResponseMessage: 'interactive',
  interactiveResponseMessage: 'interactive',
};

function evIsObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function evText(v, max) {
  if (typeof v !== 'string') return null;
  const t = v.replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, ' ').trim();
  if (t === '') return null;
  return t.length > max ? t.slice(0, max) : t;
}

function evInt(v) {
  if (typeof v === 'number') return Number.isSafeInteger(v) ? v : null;
  if (typeof v === 'string' && /^[0-9]{1,19}$/.test(v)) {
    const n = Number(v);
    return Number.isSafeInteger(n) ? n : null;
  }
  if (evIsObject(v) && typeof v.low === 'number' && (v.high === 0 || v.high === undefined)) {
    return Number.isSafeInteger(v.low) && v.low >= 0 ? v.low : null;
  }
  return null;
}

function evStripped(obj) {
  const out = {};
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v === null || v === undefined) continue;
    if (evIsObject(v) && Object.keys(v).length === 0) continue;
    out[k] = v;
  }
  return out;
}

function evHasForbiddenKey(value) {
  if (Array.isArray(value)) return value.some(evHasForbiddenKey);
  if (!evIsObject(value)) return false;
  for (const k of Object.keys(value)) {
    if (EV_FORBIDDEN_KEYS.includes(k)) return true;
    if (evHasForbiddenKey(value[k])) return true;
  }
  return false;
}

function evFail(disposition, reason) {
  return { ok: false, disposition: disposition, reason: reason };
}

function normalizeEvolutionEvent(payload) {
  if (!evIsObject(payload)) return evFail('invalid', 'payload_not_object');
  if (payload.event !== 'messages.upsert') return evFail('skipped', 'event_not_messages_upsert');

  const data = payload.data;
  if (!evIsObject(data)) return evFail('invalid', 'data_not_object');
  const key = data.key;
  if (!evIsObject(key)) return evFail('invalid', 'key_not_object');

  const remoteJid = typeof key.remoteJid === 'string' ? key.remoteJid.trim() : '';
  if (!EV_GROUP_RE.test(remoteJid)) return evFail('skipped', 'not_a_group_message');

  const instance = typeof payload.instance === 'string' ? payload.instance.trim() : '';
  if (!EV_INSTANCE_RE.test(instance)) return evFail('invalid', 'invalid_instance');

  const messageId = typeof key.id === 'string' ? key.id.trim() : '';
  if (!EV_MSGID_RE.test(messageId)) return evFail('invalid', 'invalid_message_id');

  const participant = typeof key.participant === 'string' ? key.participant.trim() : '';
  if (!EV_LID_RE.test(participant)) return evFail('invalid', 'invalid_sender_jid');

  if (typeof key.fromMe !== 'boolean') return evFail('invalid', 'invalid_from_me');

  const seconds = evInt(data.messageTimestamp);
  if (seconds === null || seconds < 1230768000 || seconds > 99999999999) {
    return evFail('invalid', 'invalid_timestamp');
  }

  const message = evIsObject(data.message) ? data.message : {};
  const declared = typeof data.messageType === 'string' ? data.messageType : null;
  const firstKey = Object.keys(message).find((k) => k !== 'messageContextInfo') || null;
  const typeKey = (declared && (EV_TYPE_BY_KEY[declared] || message[declared] !== undefined))
    ? declared
    : firstKey;
  let messageType = (typeKey && EV_TYPE_BY_KEY[typeKey]) || 'unsupported';
  if (!EV_KNOWN_TYPES.includes(messageType)) messageType = 'unsupported';

  const ext = evIsObject(message.extendedTextMessage) ? message.extendedTextMessage : {};
  const img = evIsObject(message.imageMessage) ? message.imageMessage : {};
  const vid = evIsObject(message.videoMessage) ? message.videoMessage : {};
  const aud = evIsObject(message.audioMessage) ? message.audioMessage : {};
  const doc = evIsObject(message.documentMessage) ? message.documentMessage : {};
  const stk = evIsObject(message.stickerMessage) ? message.stickerMessage : {};
  const proto = evIsObject(message.protocolMessage) ? message.protocolMessage : {};
  const album = evIsObject(message.albumMessage) ? message.albumMessage : {};
  const ctxInfo = evIsObject(ext.contextInfo) ? ext.contextInfo : {};
  const msgCtx = evIsObject(message.messageContextInfo) ? message.messageContextInfo : {};
  const assoc = evIsObject(msgCtx.messageAssociation) ? msgCtx.messageAssociation : {};
  const assocParent = evIsObject(assoc.parentMessageKey) ? assoc.parentMessageKey : {};

  const textBody = evText(message.conversation, EV_MAX_TEXT)
    ?? evText(ext.text, EV_MAX_TEXT)
    ?? evText(img.caption, EV_MAX_TEXT)
    ?? evText(vid.caption, EV_MAX_TEXT)
    ?? evText(doc.caption, EV_MAX_TEXT);

  let media = null;
  if (EV_MEDIA_TYPES.includes(messageType)) {
    const node = messageType === 'image' ? img
      : messageType === 'video' ? vid
        : messageType === 'audio' ? aud
          : messageType === 'sticker' ? stk
            : doc;
    const mime = evText(node.mimetype, 255);
    const size = evInt(node.fileLength);
    const fields = evStripped({
      mime_type: mime && /^[a-z0-9.+-]+\/[a-z0-9.+-]+(\s*;.*)?$/i.test(mime) ? mime : null,
      file_size: size !== null && size > 0 ? size : null,
    });
    if (Object.keys(fields).length > 0) media = fields;
  }

  const rawKey = evStripped({
    remoteJid: remoteJid,
    id: messageId,
    fromMe: key.fromMe,
    participant: participant,
    addressingMode: evText(key.addressingMode, 32),
  });
  const rawExtCtx = evStripped({
    stanzaId: evText(ctxInfo.stanzaId, 255),
    participant: evText(ctxInfo.participant, 64),
  });
  const rawExt = evStripped({
    text: evText(ext.text, EV_MAX_RAW_TEXT),
    contextInfo: rawExtCtx,
  });
  const rawImg = evStripped({
    mimetype: evText(img.mimetype, 255),
    fileLength: evInt(img.fileLength),
    fileSha256: evText(img.fileSha256, 128),
    width: evInt(img.width),
    height: evInt(img.height),
    caption: evText(img.caption, EV_MAX_RAW_TEXT),
  });
  const rawProto = evStripped({
    type: evText(proto.type, 64),
    id: evIsObject(proto.key) ? evText(proto.key.id, 128) : null,
  });
  const rawAlbum = evStripped({ expectedImageCount: evInt(album.expectedImageCount) });
  const rawAssoc = evStripped({
    associationType: evInt(assoc.associationType) ?? evText(assoc.associationType, 64),
    parentMessageId: evText(assocParent.id, 128),
  });
  const rawMessage = evStripped({
    conversation: evText(message.conversation, EV_MAX_RAW_TEXT),
    extendedTextMessage: rawExt,
    imageMessage: rawImg,
    protocolMessage: rawProto,
    albumMessage: rawAlbum,
    messageAssociation: rawAssoc,
  });
  const rawData = evStripped({
    key: rawKey,
    status: evText(data.status, 64),
    source: evText(data.source, 64),
    instanceId: evText(data.instanceId, 128),
    messageType: evText(declared, 64),
    messageTimestamp: seconds,
    message: rawMessage,
  });
  const rawPayload = evStripped({
    event: 'messages.upsert',
    instance: instance,
    data: rawData,
  });

  const event = evStripped({
    schema_version: 3,
    provider: 'evolution',
    instance: instance,
    group_id: remoteJid,
    provider_message_id: instance + ':' + remoteJid + ':' + messageId,
    sender_jid: participant,
    from_me: key.fromMe,
    sender_name: evText(data.pushName, 256),
    message_type: messageType,
    text_body: textBody,
    provider_timestamp: String(seconds),
    context_provider_message_id: evText(ctxInfo.stanzaId, 255),
    media: media,
    raw_payload: rawPayload,
  });

  if (evHasForbiddenKey(event)) return evFail('invalid', 'forbidden_key_present');
  const rawBytes = typeof Buffer === 'function'
    ? Buffer.byteLength(JSON.stringify(rawPayload), 'utf8')
    : new TextEncoder().encode(JSON.stringify(rawPayload)).length;
  if (rawBytes > EV_MAX_RAW_BYTES) return evFail('invalid', 'raw_payload_too_large');

  return { ok: true, event: event };
}

try {
  if (typeof module === 'object' && module && module.exports) {
    module.exports = {
      normalizeEvolutionEvent,
      EV_KNOWN_TYPES,
      EV_MEDIA_TYPES,
      EV_FORBIDDEN_KEYS,
      EV_TYPE_BY_KEY,
    };
  }
} catch (e) {
}

function demoFindBase64(value, depth = 0) {
  if (depth > 5 || value === null || typeof value !== 'object') return null;
  if (typeof value.base64 === 'string' && value.base64.length > 100) return value.base64;
  for (const v of Object.values(value)) {
    const found = demoFindBase64(v, depth + 1);
    if (found) return found;
  }
  return null;
}

const DEMO_GROUP = '__DEMO_GROUP_JID__';

const out = [];
for (const item of $input.all()) {
  const body = item.json && typeof item.json.body === 'object' && item.json.body !== null
    ? item.json.body
    : item.json;
  const result = normalizeEvolutionEvent(body);
  if (result.ok) {
    let demoMedia = null;
    const key = body?.data?.key || {};
    if (
      result.event.message_type === 'image' &&
      result.event.group_id === DEMO_GROUP
    ) {
      const b64 = demoFindBase64(body);
      if (b64) {
        demoMedia = {
          base64: b64,
          message_id: key.id,
          provider_media_id: result.event.provider_message_id,
          width: body?.data?.message?.imageMessage?.width ?? null,
          height: body?.data?.message?.imageMessage?.height ?? null,
          mime_type: body?.data?.message?.imageMessage?.mimetype || 'image/jpeg',
          timestamp: evInt(body?.data?.messageTimestamp)
        };
      }
    }
    out.push({ json: { event: result.event, _demo_media: demoMedia } });
    continue;
  }
  if (result.disposition === 'skipped') continue;
  throw new Error('Evolution event not ingestable: ' + result.reason);
}
return out;

const n = $("Normalize Evolution event").item.json;
const m = n?._demo_media;
if (!m?.base64 || !m?.provider_media_id || !m?.message_id) return [];
return [{ json: {
  provider_media_id: m.provider_media_id,
  message_id: m.message_id,
  mime_type: m.mime_type || 'image/jpeg',
  width: m.width ?? null,
  height: m.height ?? null
} }];

// Store the photo right away in the inbox; the listing it belongs to is decided later (any order of text/photos).
const m = $('Normalize Evolution event').first().json._demo_media;
const row = $json;
if (!m?.base64 || !row?.id) return [];
const EXT = { 'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
const mime = String(row.mime_type || m.mime_type || 'image/jpeg').toLowerCase().split(';')[0].trim();
const ext = EXT[mime];
if (!ext) return [];
const ct = mime === 'image/jpg' ? 'image/jpeg' : mime;
return [{ json: { media_id: row.id, path: 'inbox/' + row.id + '.' + ext, mime: ct,
  width: Number.isInteger(m.width) ? m.width : null, height: Number.isInteger(m.height) ? m.height : null },
  binary: { data: { data: m.base64, mimeType: ct, fileName: row.id + '.' + ext } } }];
